using ContosoUniversity.Models;
using ContosoUniversity.Services;
using System;
using System.Collections.Concurrent;
using System.Reflection;

namespace ContosoUniversity.Tests;

public class NotificationServiceTests : IDisposable
{
    private readonly NotificationService _sut;

    public NotificationServiceTests()
    {
        // Clear the static queue before each test
        DrainQueue();
        _sut = new NotificationService();
    }

    public void Dispose()
    {
        _sut.Dispose();
        DrainQueue();
    }

    private void DrainQueue()
    {
        // Drain the static queue by receiving all messages
        using var tempService = new NotificationService();
        while (tempService.ReceiveNotification() != null) { }
    }

    [Fact]
    public void SendNotification_WithDisplayName_CreatesCorrectMessage_ForCreate()
    {
        // Act
        _sut.SendNotification("Student", "1", "John Smith", EntityOperation.CREATE, "Admin");

        // Assert
        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("Student", notification.EntityType);
        Assert.Equal("1", notification.EntityId);
        Assert.Equal("CREATE", notification.Operation);
        Assert.Equal("New Student 'John Smith' has been created", notification.Message);
        Assert.Equal("Admin", notification.CreatedBy);
        Assert.False(notification.IsRead);
    }

    [Fact]
    public void SendNotification_WithDisplayName_CreatesCorrectMessage_ForUpdate()
    {
        _sut.SendNotification("Course", "42", "Chemistry", EntityOperation.UPDATE, "Teacher");

        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("Course 'Chemistry' has been updated", notification.Message);
        Assert.Equal("Teacher", notification.CreatedBy);
    }

    [Fact]
    public void SendNotification_WithDisplayName_CreatesCorrectMessage_ForDelete()
    {
        _sut.SendNotification("Department", "3", "Engineering", EntityOperation.DELETE);

        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("Department 'Engineering' has been deleted", notification.Message);
        Assert.Equal("System", notification.CreatedBy); // default user
    }

    [Fact]
    public void SendNotification_WithoutDisplayName_UsesIdInMessage()
    {
        _sut.SendNotification("Student", "99", EntityOperation.CREATE, "User1");

        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("New Student (ID: 99) has been created", notification.Message);
        Assert.Equal("User1", notification.CreatedBy);
    }

    [Fact]
    public void SendNotification_WithNullDisplayName_UsesIdInMessage()
    {
        _sut.SendNotification("Instructor", "5", null, EntityOperation.UPDATE);

        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("Instructor (ID: 5) has been updated", notification.Message);
    }

    [Fact]
    public void SendNotification_WithEmptyDisplayName_UsesIdInMessage()
    {
        _sut.SendNotification("Instructor", "5", "  ", EntityOperation.DELETE);

        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("Instructor (ID: 5) has been deleted", notification.Message);
    }

    [Fact]
    public void SendNotification_WithNullUserName_DefaultsToSystem()
    {
        _sut.SendNotification("Student", "1", "Test", EntityOperation.CREATE, null);

        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("System", notification.CreatedBy);
    }

    [Fact]
    public void SendNotification_SetsCreatedAtToCurrentTime()
    {
        var before = DateTime.Now;
        _sut.SendNotification("Student", "1", "Test", EntityOperation.CREATE);
        var after = DateTime.Now;

        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.InRange(notification.CreatedAt, before, after);
    }

    [Fact]
    public void ReceiveNotification_ReturnsNull_WhenQueueIsEmpty()
    {
        var result = _sut.ReceiveNotification();
        Assert.Null(result);
    }

    [Fact]
    public void ReceiveNotification_ReturnsMessagesInFifoOrder()
    {
        _sut.SendNotification("Student", "1", "First", EntityOperation.CREATE);
        _sut.SendNotification("Course", "2", "Second", EntityOperation.UPDATE);

        var first = _sut.ReceiveNotification();
        var second = _sut.ReceiveNotification();

        Assert.NotNull(first);
        Assert.NotNull(second);
        Assert.Equal("1", first.EntityId);
        Assert.Equal("2", second.EntityId);
    }

    [Fact]
    public void ReceiveNotification_RemovesMessageFromQueue()
    {
        _sut.SendNotification("Student", "1", EntityOperation.CREATE);

        var first = _sut.ReceiveNotification();
        var second = _sut.ReceiveNotification();

        Assert.NotNull(first);
        Assert.Null(second);
    }

    [Fact]
    public void MarkAsRead_DoesNotThrow()
    {
        // MarkAsRead is a no-op for in-memory implementation
        var ex = Record.Exception(() => _sut.MarkAsRead(42));
        Assert.Null(ex);
    }

    [Fact]
    public void SendNotification_TwoArgOverload_DelegatesToFiveArgOverload()
    {
        _sut.SendNotification("Course", "100", EntityOperation.DELETE);

        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("Course (ID: 100) has been deleted", notification.Message);
        Assert.Equal("DELETE", notification.Operation);
        Assert.Equal("Course", notification.EntityType);
        Assert.Equal("100", notification.EntityId);
    }

    [Fact]
    public void Dispose_DoesNotThrow()
    {
        var service = new NotificationService();
        var ex = Record.Exception(() => service.Dispose());
        Assert.Null(ex);
    }
}

