using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.EntityFrameworkCore;
using System;
using System.Linq;

namespace ContosoUniversity.Tests;

public class DbInitializerTests
{
    [Fact]
    public void Initialize_SeedsStudents()
    {
        using var context = TestHelpers.CreateInMemoryContext();

        DbInitializer.Initialize(context);

        Assert.Equal(8, context.Students.Count());
        Assert.Contains(context.Students, s => s.LastName == "Alexander" && s.FirstMidName == "Carson");
        Assert.Contains(context.Students, s => s.LastName == "Olivetto" && s.FirstMidName == "Nino");
    }

    [Fact]
    public void Initialize_SeedsInstructors()
    {
        using var context = TestHelpers.CreateInMemoryContext();

        DbInitializer.Initialize(context);

        Assert.Equal(5, context.Instructors.Count());
        Assert.Contains(context.Instructors, i => i.LastName == "Abercrombie" && i.FirstMidName == "Kim");
        Assert.Contains(context.Instructors, i => i.LastName == "Zheng" && i.FirstMidName == "Roger");
    }

    [Fact]
    public void Initialize_SeedsDepartments()
    {
        using var context = TestHelpers.CreateInMemoryContext();

        DbInitializer.Initialize(context);

        Assert.Equal(4, context.Departments.Count());
        Assert.Contains(context.Departments, d => d.Name == "English" && d.Budget == 350000);
        Assert.Contains(context.Departments, d => d.Name == "Economics" && d.Budget == 100000);
    }

    [Fact]
    public void Initialize_SeedsCourses()
    {
        using var context = TestHelpers.CreateInMemoryContext();

        DbInitializer.Initialize(context);

        Assert.Equal(7, context.Courses.Count());
        Assert.Contains(context.Courses, c => c.Title == "Chemistry" && c.CourseID == 1050);
        Assert.Contains(context.Courses, c => c.Title == "Literature" && c.CourseID == 2042);
    }

    [Fact]
    public void Initialize_SeedsOfficeAssignments()
    {
        using var context = TestHelpers.CreateInMemoryContext();

        DbInitializer.Initialize(context);

        Assert.Equal(3, context.OfficeAssignments.Count());
        Assert.Contains(context.OfficeAssignments, o => o.Location == "Smith 17");
        Assert.Contains(context.OfficeAssignments, o => o.Location == "Thompson 304");
    }

    [Fact]
    public void Initialize_SeedsCourseAssignments()
    {
        using var context = TestHelpers.CreateInMemoryContext();

        DbInitializer.Initialize(context);

        Assert.Equal(8, context.CourseAssignments.Count());
    }

    [Fact]
    public void Initialize_SeedsEnrollments()
    {
        using var context = TestHelpers.CreateInMemoryContext();

        DbInitializer.Initialize(context);

        Assert.Equal(11, context.Enrollments.Count());
        // Verify specific enrollments with grades
        var alexanderChemistry = context.Enrollments
            .Single(e => e.Student.LastName == "Alexander" && e.Course.Title == "Chemistry");
        Assert.Equal(Grade.A, alexanderChemistry.Grade);
    }

    [Fact]
    public void Initialize_DoesNotReseed_WhenStudentsExist()
    {
        using var context = TestHelpers.CreateInMemoryContext();

        // First seed
        DbInitializer.Initialize(context);
        var initialStudentCount = context.Students.Count();

        // Second seed — should be a no-op
        DbInitializer.Initialize(context);
        var afterSecondSeed = context.Students.Count();

        Assert.Equal(initialStudentCount, afterSecondSeed);
        Assert.Equal(8, afterSecondSeed);
    }

    [Fact]
    public void Initialize_DoesNotDuplicateEnrollments()
    {
        using var context = TestHelpers.CreateInMemoryContext();

        DbInitializer.Initialize(context);

        // Verify no duplicates: each student-course pair should appear only once
        var duplicates = context.Enrollments
            .GroupBy(e => new { e.StudentID, e.CourseID })
            .Where(g => g.Count() > 1)
            .ToList();

        Assert.Empty(duplicates);
    }

    [Fact]
    public void Initialize_SetsDepartmentAdministrators()
    {
        using var context = TestHelpers.CreateInMemoryContext();

        DbInitializer.Initialize(context);

        var englishDept = context.Departments.Single(d => d.Name == "English");
        Assert.NotNull(englishDept.InstructorID);

        // The English department administrator should be Abercrombie
        var admin = context.Instructors.Find(englishDept.InstructorID);
        Assert.NotNull(admin);
        Assert.Equal("Abercrombie", admin.LastName);
    }

    [Fact]
    public void Initialize_CourseCreditsAreCorrect()
    {
        using var context = TestHelpers.CreateInMemoryContext();

        DbInitializer.Initialize(context);

        var calculus = context.Courses.Single(c => c.Title == "Calculus");
        Assert.Equal(4, calculus.Credits);
        Assert.Equal(1045, calculus.CourseID);

