    }

    // ---- Edit POST ----

    [Fact]
    public void Edit_Post_ValidCourse_RedirectsToIndex()
    {
        var course = _context.Courses.First();
        _context.Entry(course).State = EntityState.Detached;

        var updated = new Course
        {
            CourseID = course.CourseID,
            Title = "Updated Title",
            Credits = 4,
            DepartmentID = course.DepartmentID
        };

        var result = _controller.Edit(updated, null!);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
    }

    [Fact]
    public void Edit_Post_InvalidModelState_ReturnsView()
    {
        _controller.ModelState.AddModelError("Title", "Required");
        var course = new Course { CourseID = 1050 };

        var result = _controller.Edit(course, null!);

        Assert.IsType<ViewResult>(result);
        Assert.NotNull(_controller.ViewBag.DepartmentID);
    }

    [Fact]
    public void Edit_Post_InvalidImageExtension_ReturnsViewWithError()
    {
        var course = _context.Courses.First();
        _context.Entry(course).State = EntityState.Detached;

        var updatedCourse = new Course
        {
            CourseID = course.CourseID,
            Title = course.Title,
            Credits = course.Credits,
            DepartmentID = course.DepartmentID
        };

        var fileMock = new Mock<IFormFile>();
        fileMock.Setup(f => f.Length).Returns(1024);
        fileMock.Setup(f => f.FileName).Returns("file.pdf");

        var result = _controller.Edit(updatedCourse, fileMock.Object);

        Assert.IsType<ViewResult>(result);
        Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
    }

    [Fact]
    public void Edit_Post_FileTooLarge_ReturnsViewWithError()
    {
        var course = _context.Courses.First();
        _context.Entry(course).State = EntityState.Detached;

        var updatedCourse = new Course
        {
            CourseID = course.CourseID,
            Title = course.Title,
            Credits = course.Credits,
            DepartmentID = course.DepartmentID
        };

        var fileMock = new Mock<IFormFile>();
        fileMock.Setup(f => f.Length).Returns(10 * 1024 * 1024); // 10MB
        fileMock.Setup(f => f.FileName).Returns("big.png");

        var result = _controller.Edit(updatedCourse, fileMock.Object);

        Assert.IsType<ViewResult>(result);
        Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
    }

    // ---- Delete GET ----

    [Fact]
    public void Delete_Get_NullId_ReturnsBadRequest()
    {
        var result = _controller.Delete(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal((int)HttpStatusCode.BadRequest, statusResult.StatusCode);
    }

    [Fact]
    public void Delete_Get_ValidId_ReturnsViewWithCourse()
    {
        var course = _context.Courses.First();

        var result = _controller.Delete(course.CourseID);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Course>(viewResult.Model);
        Assert.Equal(course.CourseID, model.CourseID);
    }

    // ---- Delete POST ----

    [Fact]
    public void DeleteConfirmed_RemovesCourseFromDatabase()
    {
        var course = _context.Courses.First();
        var initialCount = _context.Courses.Count();

        var result = _controller.DeleteConfirmed(course.CourseID);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
        Assert.Equal(initialCount - 1, _context.Courses.Count());
    }

    // ---- Image extension validation ----

    [Theory]
    [InlineData("photo.jpg")]
    [InlineData("image.jpeg")]
    [InlineData("picture.png")]
    [InlineData("animation.gif")]
    [InlineData("bitmap.bmp")]
    public void Create_Post_AllowedImageExtensions_DoNotCauseExtensionError(string filename)
    {
        var course = new Course
        {
            CourseID = 5555,
            Title = "Image Test",
            Credits = 3,
            DepartmentID = _context.Departments.First().DepartmentID
        };

        var fileMock = new Mock<IFormFile>();
        fileMock.Setup(f => f.Length).Returns(1024);
        fileMock.Setup(f => f.FileName).Returns(filename);
        // The file upload will fail because the path doesn't exist,
        // but it should not fail on extension validation
        var result = _controller.Create(course, fileMock.Object);

        // Should not have the "valid image file" error, but may have upload error
        if (_controller.ModelState.ContainsKey("teachingMaterialImage"))
        {
            var errors = _controller.ModelState["teachingMaterialImage"]!.Errors;
            Assert.DoesNotContain(errors, e => e.ErrorMessage.Contains("valid image file"));
        }
    }
}

