using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Models.SchoolViewModels;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.ViewFeatures;
using Microsoft.EntityFrameworkCore;
using System;
using System.Collections.Generic;
using System.Linq;
using System.Net;

namespace ContosoUniversity.Tests;

public class InstructorsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly InstructorsController _controller;

    public InstructorsControllerTests()
    {
        _context = TestHelpers.CreateSeededContext();
        // Add course assignments and office assignments for instructor tests
        SeedInstructorRelations();
        _controller = new InstructorsController(_context);
        _controller.TempData = new TempDataDictionary(
            new DefaultHttpContext(), new SessionStateTempDataProvider());
    }

    private void SeedInstructorRelations()
    {
        var instructor = _context.Instructors.First();
        var course = _context.Courses.First();

        if (!_context.CourseAssignments.Any())
        {
            _context.CourseAssignments.Add(new CourseAssignment
            {
                InstructorID = instructor.ID,
                CourseID = course.CourseID
            });
            _context.SaveChanges();
        }
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
    }

    // ---- Index ----

    [Fact]
    public void Index_NoParams_ReturnsViewWithInstructorIndexData()
    {
        var result = _controller.Index(null, null);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<InstructorIndexData>(viewResult.Model);
        Assert.NotNull(model.Instructors);
        Assert.Equal(2, model.Instructors.Count()); // 2 seeded instructors
    }

    [Fact]
    public void Index_WithInstructorId_PopulatesCourses()
    {
        var instructor = _context.Instructors.First();

        var result = _controller.Index(instructor.ID, null);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<InstructorIndexData>(viewResult.Model);
        Assert.NotNull(model.Courses);
        Assert.NotEmpty(model.Courses);
    }

    // ---- Details ----

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        var result = _controller.Details(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal((int)HttpStatusCode.BadRequest, statusResult.StatusCode);
    }

    [Fact]
    public void Details_InvalidId_ReturnsNotFound()
    {
        var result = _controller.Details(9999);

        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void Details_ValidId_ReturnsViewWithInstructor()
    {
        var instructor = _context.Instructors.First();

        var result = _controller.Details(instructor.ID);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Instructor>(viewResult.Model);
        Assert.Equal(instructor.ID, model.ID);
        Assert.Equal(instructor.LastName, model.LastName);
    }

    // ---- Create GET ----

    [Fact]
    public void Create_Get_ReturnsViewWithCourseData()
    {
        var result = _controller.Create();

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Instructor>(viewResult.Model);
        Assert.NotNull(model.CourseAssignments);
        Assert.NotNull(_controller.ViewBag.Courses);
    }

    // ---- Create POST ----

    [Fact]
    public void Create_Post_ValidInstructor_RedirectsToIndex()
    {
        var instructor = new Instructor
        {
            FirstMidName = "New",
            LastName = "Instructor",
            HireDate = new DateTime(2023, 1, 1),
            CourseAssignments = new List<CourseAssignment>()
        };

        var result = _controller.Create(instructor, null!);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
    }

    [Fact]
    public void Create_Post_ValidInstructor_AddsToDatabase()
    {
        var initialCount = _context.Instructors.Count();
        var instructor = new Instructor
        {
            FirstMidName = "Added",
            LastName = "Teacher",
            HireDate = new DateTime(2023, 6, 1),
            CourseAssignments = new List<CourseAssignment>()
        };

        _controller.Create(instructor, null!);

        Assert.Equal(initialCount + 1, _context.Instructors.Count());
        Assert.Contains(_context.Instructors, i => i.LastName == "Teacher" && i.FirstMidName == "Added");
    }

    [Fact]
    public void Create_Post_WithSelectedCourses_AddsCourseAssignments()
    {
        var course = _context.Courses.First();
        var instructor = new Instructor
        {
            FirstMidName = "With",
            LastName = "Courses",
            HireDate = new DateTime(2023, 1, 1)
        };
        var selectedCourses = new[] { course.CourseID.ToString() };

        _controller.Create(instructor, selectedCourses);

        var saved = _context.Instructors.Include(i => i.CourseAssignments)
            .Single(i => i.LastName == "Courses");
        Assert.Single(saved.CourseAssignments);
        Assert.Equal(course.CourseID, saved.CourseAssignments.First().CourseID);
    }

    [Fact]
    public void Create_Post_InvalidModelState_ReturnsView()
    {
        _controller.ModelState.AddModelError("LastName", "Required");
        var instructor = new Instructor
        {
            HireDate = new DateTime(2023, 1, 1),
            CourseAssignments = new List<CourseAssignment>()
        };

        var result = _controller.Create(instructor, null!);

        Assert.IsType<ViewResult>(result);
        Assert.NotNull(_controller.ViewBag.Courses);
    }

    // ---- Edit GET ----

    [Fact]
    public void Edit_Get_NullId_ReturnsBadRequest()
    {
        var result = _controller.Edit((int?)null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal((int)HttpStatusCode.BadRequest, statusResult.StatusCode);
    }

    [Fact]
    public void Edit_Get_ValidId_ReturnsViewWithInstructor()
    {
        var instructor = _context.Instructors.First();

        var result = _controller.Edit((int?)instructor.ID);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Instructor>(viewResult.Model);
        Assert.Equal(instructor.ID, model.ID);
        Assert.NotNull(_controller.ViewBag.Courses);
    }

    // ---- Delete GET ----

    [Fact]
    public void Delete_Get_NullId_ReturnsBadRequest()
    {
        var result = _controller.Delete(null);

        var statusResult = Assert.IsType<StatusCodeResult>(result);
        Assert.Equal((int)HttpStatusCode.BadRequest, statusResult.StatusCode);
    }

    [Fact]
    public void Delete_Get_InvalidId_ReturnsNotFound()
    {
        var result = _controller.Delete(9999);

        Assert.IsType<NotFoundResult>(result);
    }

    [Fact]
    public void Delete_Get_ValidId_ReturnsViewWithInstructor()
    {
        var instructor = _context.Instructors.First();

        var result = _controller.Delete(instructor.ID);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsType<Instructor>(viewResult.Model);
        Assert.Equal(instructor.ID, model.ID);
    }

    // ---- Delete POST ----

    [Fact]
    public void DeleteConfirmed_RemovesInstructorFromDatabase()
    {
        // Use second instructor (no department administrator conflicts)
        var instructor = _context.Instructors.OrderBy(i => i.ID).Last();
        var initialCount = _context.Instructors.Count();

        var result = _controller.DeleteConfirmed(instructor.ID);

        var redirect = Assert.IsType<RedirectToActionResult>(result);
        Assert.Equal("Index", redirect.ActionName);
        Assert.Equal(initialCount - 1, _context.Instructors.Count());
    }

    [Fact]
    public void DeleteConfirmed_NullsDepartmentAdministrator()
    {
        // Instructor ID 10 is administrator of English department
        var instructor = _context.Instructors.Single(i => i.ID == 10);
        var dept = _context.Departments.Single(d => d.InstructorID == 10);

        _controller.DeleteConfirmed(instructor.ID);

        var updatedDept = _context.Departments.Find(dept.DepartmentID);
        Assert.NotNull(updatedDept);
        Assert.Null(updatedDept.InstructorID);
    }
}

