using System;
using System.Collections.Generic;

namespace ContosoUniversity.Tests;

public class NotificationsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly NotificationsController _controller;

    public NotificationsControllerTests()
    {
        // Drain the static notification queue before each test
        DrainNotificationQueue();
        _context = TestHelpers.CreateInMemoryContext();
        _controller = new NotificationsController(_context);
        _controller.TempData = new TempDataDictionary(
            new DefaultHttpContext(), new SessionStateTempDataProvider());
    }

    public void Dispose()
    {
        _controller.Dispose();
        _context.Dispose();
        DrainNotificationQueue();
    }

    private void DrainNotificationQueue()
    {
        using var svc = new NotificationService();
        while (svc.ReceiveNotification() != null) { }
    }

    [Fact]
    public void Index_ReturnsViewResult()
    {
        var result = _controller.Index();

        Assert.IsType<ViewResult>(result);
    }

    [Fact]
    public void GetNotifications_EmptyQueue_ReturnsSuccessWithZeroCount()
    {
        var result = _controller.GetNotifications();

        var jsonResult = Assert.IsType<JsonResult>(result);
        Assert.NotNull(jsonResult.Value);

        // Use reflection to read anonymous type properties
        var value = jsonResult.Value!;
        var successProp = value.GetType().GetProperty("success");
        var countProp = value.GetType().GetProperty("count");

        Assert.NotNull(successProp);
        Assert.NotNull(countProp);
        Assert.True((bool)successProp.GetValue(value)!);
        Assert.Equal(0, (int)countProp.GetValue(value)!);
    }

    [Fact]
    public void GetNotifications_WithNotifications_ReturnsThemInOrder()
    {
        // Enqueue notifications via the controller's notification service
        using var svc = new NotificationService();
        svc.SendNotification("Student", "1", "Alice", EntityOperation.CREATE);
        svc.SendNotification("Course", "2", "Math", EntityOperation.UPDATE);

        var result = _controller.GetNotifications();

        var jsonResult = Assert.IsType<JsonResult>(result);
        var value = jsonResult.Value!;
        var successProp = value.GetType().GetProperty("success");
        var countProp = value.GetType().GetProperty("count");
        var notificationsProp = value.GetType().GetProperty("notifications");

        Assert.True((bool)successProp!.GetValue(value)!);
        Assert.Equal(2, (int)countProp!.GetValue(value)!);

        var notifications = (List<Notification>)notificationsProp!.GetValue(value)!;
        Assert.Equal("Student", notifications[0].EntityType);
        Assert.Equal("Course", notifications[1].EntityType);
    }

    [Fact]
    public void GetNotifications_LimitsToTenMessages()
    {
        using var svc = new NotificationService();
        for (int i = 0; i < 15; i++)
        {
            svc.SendNotification("Entity", i.ToString(), EntityOperation.CREATE);
        }

        var result = _controller.GetNotifications();

        var jsonResult = Assert.IsType<JsonResult>(result);
        var value = jsonResult.Value!;
        var countProp = value.GetType().GetProperty("count");
        Assert.Equal(10, (int)countProp!.GetValue(value)!);
    }

    [Fact]
    public void MarkAsRead_ReturnsSuccessJson()
    {
        var result = _controller.MarkAsRead(1);

        var jsonResult = Assert.IsType<JsonResult>(result);
        var value = jsonResult.Value!;
        var successProp = value.GetType().GetProperty("success");
        Assert.True((bool)successProp!.GetValue(value)!);
    }
}

public class SchoolContextTests
{
    [Fact]
    public void SchoolContext_CanCreateAndQueryEntities()
    {
        using var context = TestHelpers.CreateInMemoryContext();

        var student = new Student
        {
            FirstMidName = "Test",
            LastName = "User",
            EnrollmentDate = new DateTime(2023, 1, 1)
        };

        context.Students.Add(student);
        context.SaveChanges();

        var retrieved = context.Students.Single(s => s.LastName == "User");
        Assert.Equal("Test", retrieved.FirstMidName);
        Assert.Equal(new DateTime(2023, 1, 1), retrieved.EnrollmentDate);
    }

    [Fact]
    public void SchoolContext_HasAllExpectedDbSets()
    {
        using var context = TestHelpers.CreateInMemoryContext();

        Assert.NotNull(context.Courses);
        Assert.NotNull(context.Enrollments);
        Assert.NotNull(context.Departments);
        Assert.NotNull(context.OfficeAssignments);
        Assert.NotNull(context.CourseAssignments);
        Assert.NotNull(context.People);
        Assert.NotNull(context.Students);
        Assert.NotNull(context.Instructors);
        Assert.NotNull(context.Notifications);
    }

    [Fact]
    public void SchoolContext_CourseAssignment_HasCompositeKey()
    {
        using var context = TestHelpers.CreateInMemoryContext();

        var instructor = new Instructor
        {
            FirstMidName = "Test",
            LastName = "Instructor",
            HireDate = new DateTime(2020, 1, 1)
        };
        context.Instructors.Add(instructor);

        var course = new Course
        {
            CourseID = 9999,
            Title = "Test Course",
            Credits = 3,
            DepartmentID = 0
        };
        context.Courses.Add(course);
        context.SaveChanges();

        var ca = new CourseAssignment
        {
            InstructorID = instructor.ID,
            CourseID = course.CourseID
        };
        context.CourseAssignments.Add(ca);
        context.SaveChanges();

        var retrieved = context.CourseAssignments
            .Single(c => c.InstructorID == instructor.ID && c.CourseID == course.CourseID);
        Assert.Equal(instructor.ID, retrieved.InstructorID);
        Assert.Equal(course.CourseID, retrieved.CourseID);
    }
}

