[Fact]
public void Initialize_DoesNotDuplicateEnrollments()
{
    using var context = TestHelpers.CreateInMemoryContext();

    DbInitializer.Initialize(context);

    // Verify no duplicates: each student-course pair should appear only once
    var enrollments = context.Enrollments.ToList();
    var duplicates = enrollments
        .GroupBy(e => new { e.StudentID, e.CourseID })
        .Where(g => g.Count() > 1)
        .ToList();

    Assert.Empty(duplicates);
}

