using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.ViewFeatures;
using Microsoft.EntityFrameworkCore;
using Moq;
using System;
using System.Collections.Generic;
using System.Linq;
using System.Net;
using Microsoft.AspNetCore.Hosting;
using Microsoft.Extensions.Logging;
using ContosoUniversity.Models.SchoolViewModels;

namespace ContosoUniversity.Tests;

/// <summary>
/// Tests targeting gaps identified by mutation analysis: boundary conditions,
/// edge cases, and mutation-surviving paths.
/// </summary>
public class MutationGapTests
{
    // ---- NotificationService: Queue max enforcement ----

    [Fact]
    public void NotificationService_EnforcesMaxQueueLength()
    {
        // Drain queue first
        using var drainer = new NotificationService();
        while (drainer.ReceiveNotification() != null) { }

        using var sut = new NotificationService();

        // Enqueue more than 500 (the internal limit)
        for (int i = 0; i < 510; i++)
        {
            sut.SendNotification("Entity", i.ToString(), $"Item {i}", EntityOperation.CREATE, "User");
        }

        // Drain and count
        int received = 0;
        while (sut.ReceiveNotification() != null) received++;

        // Should be capped at 500 (the _maxQueueLength)
        Assert.True(received <= 500, $"Expected at most 500 notifications, got {received}");
        Assert.True(received >= 490, $"Expected at least ~500 notifications, got {received}"); // best-effort enforcement
    }

    // ---- StudentsController: Date boundary validation ----

    [Theory]
    [InlineData(1753, 1, 1, true)]   // Exactly at SQL min boundary — should be valid
    [InlineData(1752, 12, 31, false)] // One day before — should be invalid
    [InlineData(2023, 6, 15, true)]   // Normal date — should be valid
    public void StudentsController_Create_DateBoundaryValidation(int year, int month, int day, bool shouldBeValid)
    {
        using var context = TestHelpers.CreateInMemoryContext();
        using var controller = new StudentsController(context);
        controller.TempData = new TempDataDictionary(new DefaultHttpContext(), Mock.Of<ITempDataProvider>());

        var student = new Student
        {
            FirstMidName = "Boundary",
            LastName = "Test",
            EnrollmentDate = new DateTime(year, month, day)
        };

        var result = controller.Create(student);

        if (shouldBeValid)
        {
            Assert.IsType<RedirectToActionResult>(result);
        }
        else
        {
            Assert.IsType<ViewResult>(result);
            Assert.True(controller.ModelState.ContainsKey("EnrollmentDate"));
        }
    }

    [Theory]
    [InlineData(1753, 1, 1, true)]
    [InlineData(1752, 12, 31, false)]
    public void StudentsController_Edit_DateBoundaryValidation(int year, int month, int day, bool shouldBeValid)
    {
        using var context = TestHelpers.CreateSeededContext();
        var existingStudent = context.Students.First();
        context.Entry(existingStudent).State = EntityState.Detached;

        using var controller = new StudentsController(context);
        controller.TempData = new TempDataDictionary(new DefaultHttpContext(), Mock.Of<ITempDataProvider>());

        var student = new Student
        {
            ID = existingStudent.ID,
            FirstMidName = "Updated",
            LastName = "Student",
            EnrollmentDate = new DateTime(year, month, day)
        };

        var result = controller.Edit(student);

        if (shouldBeValid)
        {
            Assert.IsType<RedirectToActionResult>(result);
        }
        else
        {
            Assert.IsType<ViewResult>(result);
            Assert.True(controller.ModelState.ContainsKey("EnrollmentDate"));
        }
    }

    // ---- CoursesController: File size at exact 5MB boundary ----

    [Fact]
    public void CoursesController_Create_ExactlyFiveMB_IsAllowed()
    {
        using var context = TestHelpers.CreateSeededContext();
        var envMock = new Mock<IWebHostEnvironment>();
        envMock.Setup(e => e.WebRootPath).Returns((string?)null);
        envMock.Setup(e => e.ContentRootPath).Returns("/fake/path");
        var loggerMock = new Mock<ILogger<CoursesController>>();

        using var controller = new CoursesController(context, envMock.Object, loggerMock.Object);
        controller.TempData = new TempDataDictionary(new DefaultHttpContext(), Mock.Of<ITempDataProvider>());

        var course = new Course
        {
            CourseID = 5555,
            Title = "Boundary Test",
            Credits = 3,
            DepartmentID = context.Departments.First().DepartmentID
        };

        var fileMock = new Mock<IFormFile>();
        fileMock.Setup(f => f.Length).Returns(5 * 1024 * 1024); // Exactly 5MB
        fileMock.Setup(f => f.FileName).Returns("exact5mb.jpg");

        var result = controller.Create(course, fileMock.Object);

        // Should NOT fail on size validation (might fail on file write, but not size check)
        if (controller.ModelState.ContainsKey("teachingMaterialImage"))
        {
            var errors = controller.ModelState["teachingMaterialImage"]!.Errors;
            Assert.DoesNotContain(errors, e => e.ErrorMessage.Contains("5MB"));
        }
    }

    [Fact]
    public void CoursesController_Create_OneBytOverFiveMB_IsRejected()
    {
        using var context = TestHelpers.CreateSeededContext();
        var envMock = new Mock<IWebHostEnvironment>();
        envMock.Setup(e => e.WebRootPath).Returns((string?)null);
        envMock.Setup(e => e.ContentRootPath).Returns("/fake/path");
        var loggerMock = new Mock<ILogger<CoursesController>>();

        using var controller = new CoursesController(context, envMock.Object, loggerMock.Object);
        controller.TempData = new TempDataDictionary(new DefaultHttpContext(), Mock.Of<ITempDataProvider>());

        var course = new Course
        {
            CourseID = 5556,
            Title = "Over Limit",
            Credits = 3,
            DepartmentID = context.Departments.First().DepartmentID
        };

        var fileMock = new Mock<IFormFile>();
        fileMock.Setup(f => f.Length).Returns(5 * 1024 * 1024 + 1); // 5MB + 1 byte
        fileMock.Setup(f => f.FileName).Returns("toobig.jpg");

        var result = controller.Create(course, fileMock.Object);

        Assert.IsType<ViewResult>(result);
        Assert.True(controller.ModelState.ContainsKey("teachingMaterialImage"));
        var errors = controller.ModelState["teachingMaterialImage"]!.Errors;
        Assert.Contains(errors, e => e.ErrorMessage.Contains("5MB"));
    }

    // ---- CoursesController: Case-insensitive extension check ----

    [Theory]
    [InlineData("photo.JPG")]
    [InlineData("image.Png")]
    [InlineData("file.GIF")]
    [InlineData("pic.JPEG")]
    [InlineData("img.BMP")]
    public void CoursesController_Create_UppercaseImageExtension_IsAllowed(string filename)
    {
        using var context = TestHelpers.CreateSeededContext();
        var envMock = new Mock<IWebHostEnvironment>();
        envMock.Setup(e => e.WebRootPath).Returns((string?)null);
        envMock.Setup(e => e.ContentRootPath).Returns("/fake/path");
        var loggerMock = new Mock<ILogger<CoursesController>>();

        using var controller = new CoursesController(context, envMock.Object, loggerMock.Object);
        controller.TempData = new TempDataDictionary(new DefaultHttpContext(), Mock.Of<ITempDataProvider>());

        var course = new Course
        {
            CourseID = 4444,
            Title = "Case Test",
            Credits = 3,
            DepartmentID = context.Departments.First().DepartmentID
        };

        var fileMock = new Mock<IFormFile>();
        fileMock.Setup(f => f.Length).Returns(1024);
        fileMock.Setup(f => f.FileName).Returns(filename);

        var result = controller.Create(course, fileMock.Object);

        // Should not fail on extension validation
        if (controller.ModelState.ContainsKey("teachingMaterialImage"))
        {
            var errors = controller.ModelState["teachingMaterialImage"]!.Errors;
            Assert.DoesNotContain(errors, e => e.ErrorMessage.Contains("valid image file"));
        }
    }

    // ---- NotificationsController: Exact limit of 10 ----

    [Fact]
    public void NotificationsController_GetNotifications_ExactlyTen_ReturnsAll()
    {
        // Drain queue
        using var drainer = new NotificationService();
        while (drainer.ReceiveNotification() != null) { }

        using var svc = new NotificationService();
        for (int i = 0; i < 10; i++)
        {
            svc.SendNotification("Test", i.ToString(), EntityOperation.CREATE);
        }

        using var context = TestHelpers.CreateInMemoryContext();
        using var controller = new NotificationsController(context);
        controller.TempData = new TempDataDictionary(new DefaultHttpContext(), Mock.Of<ITempDataProvider>());

        var result = controller.GetNotifications();

        var jsonResult = Assert.IsType<JsonResult>(result);
        var value = jsonResult.Value!;
        var countProp = value.GetType().GetProperty("count");
        Assert.Equal(10, (int)countProp!.GetValue(value)!);
    }

    [Fact]
    public void NotificationsController_GetNotifications_ElevenQueued_ReturnsOnlyTen()
    {
        // Drain queue
        using var drainer = new NotificationService();
        while (drainer.ReceiveNotification() != null) { }

        using var svc = new NotificationService();
        for (int i = 0; i < 11; i++)
        {
            svc.SendNotification("Test", i.ToString(), EntityOperation.CREATE);
        }

        using var context = TestHelpers.CreateInMemoryContext();
        using var controller = new NotificationsController(context);
        controller.TempData = new TempDataDictionary(new DefaultHttpContext(), Mock.Of<ITempDataProvider>());

        var result = controller.GetNotifications();

        var jsonResult = Assert.IsType<JsonResult>(result);
        var value = jsonResult.Value!;
        var countProp = value.GetType().GetProperty("count");
        Assert.Equal(10, (int)countProp!.GetValue(value)!);
    }

    // ---- StudentsController: Index with unknown sort falls to default (ascending by LastName) ----

    [Fact]
    public void StudentsController_Index_UnknownSortOrder_DefaultsToLastNameAscending()
    {
        using var context = TestHelpers.CreateSeededContext();
        using var controller = new StudentsController(context);
        controller.TempData = new TempDataDictionary(new DefaultHttpContext(), Mock.Of<ITempDataProvider>());

        var result = controller.Index("unknown_value", null, null, null);

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<PaginatedList<Student>>(viewResult.Model);
        // Default is OrderBy LastName ascending
        Assert.Equal("Alexander", model[0].LastName);
        Assert.Equal("Anand", model[^1].LastName);
    }

    // ---- HomeController: About with empty database returns empty list ----

    [Fact]
    public void HomeController_About_EmptyDatabase_ReturnsEmptyList()
    {
        using var context = TestHelpers.CreateInMemoryContext(); // no seeding
        using var controller = new HomeController(context);
        controller.TempData = new TempDataDictionary(new DefaultHttpContext(), Mock.Of<ITempDataProvider>());

        var result = controller.About();

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<List<EnrollmentDateGroup>>(viewResult.Model);
        Assert.Empty(model);
    }

    // ---- HomeController: About verifies correct grouping key (EnrollmentDate) ----

    [Fact]
    public void HomeController_About_GroupsByEnrollmentDate_CorrectDates()
    {
        using var context = TestHelpers.CreateSeededContext();
        using var controller = new HomeController(context);
        controller.TempData = new TempDataDictionary(new DefaultHttpContext(), Mock.Of<ITempDataProvider>());

        var result = controller.About();

        var viewResult = Assert.IsType<ViewResult>(result);
        var model = Assert.IsAssignableFrom<List<EnrollmentDateGroup>>(viewResult.Model);

        // Seeded dates: 2010-09-01 (1 student), 2012-09-01 (1 student), 2013-09-01 (1 student)
        var dates = model.Select(g => g.EnrollmentDate).OrderBy(d => d).ToList();
        Assert.Contains(dates, d => d.HasValue && d.Value.Year == 2010);
        Assert.Contains(dates, d => d.HasValue && d.Value.Year == 2012);
        Assert.Contains(dates, d => d.HasValue && d.Value.Year == 2013);

        // Verify each group has exactly 1 student
        Assert.All(model, g => Assert.Equal(1, g.StudentCount));
    }

    // ---- InstructorsController: DeleteConfirmed actually nulls department administrator ----

    [Fact]
    public void InstructorsController_DeleteConfirmed_NullsDepartmentAdmin_VerifyInDatabase()
    {
        using var context = TestHelpers.CreateSeededContext();
        var instructor = context.Instructors.Single(i => i.ID == 10);

        // Verify department has administrator before delete
        var deptBefore = context.Departments.Single(d => d.InstructorID == 10);
        Assert.Equal(10, deptBefore.InstructorID);

        using var controller = new InstructorsController(context);
        controller.TempData = new TempDataDictionary(new DefaultHttpContext(), Mock.Of<ITempDataProvider>());

        controller.DeleteConfirmed(instructor.ID);

        // Verify department's InstructorID is now null
        var deptAfter = context.Departments.Find(deptBefore.DepartmentID);
        Assert.NotNull(deptAfter);
        Assert.Null(deptAfter.InstructorID);
    }

    // ---- NotificationService: GenerateMessage default case ----

    [Fact]
    public void NotificationService_SendNotification_WithDisplayName_CorrectFormat_Create()
    {
        using var drainer = new NotificationService();
        while (drainer.ReceiveNotification() != null) { }

        using var sut = new NotificationService();
        sut.SendNotification("Student", "42", "John Doe", EntityOperation.CREATE, "Admin");

        var notification = sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("New Student 'John Doe' has been created", notification.Message);
        // Verify it's not using ID format when display name is provided
        Assert.DoesNotContain("ID:", notification.Message);
    }

    [Fact]
    public void NotificationService_SendNotification_Update_CorrectFormat()
    {
        using var drainer = new NotificationService();
        while (drainer.ReceiveNotification() != null) { }

        using var sut = new NotificationService();
