        var notification = sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("Course 'Physics' has been updated", notification.Message);
        Assert.DoesNotContain("New", notification.Message); // Update != Create
    }

    [Fact]
    public void NotificationService_SendNotification_Delete_CorrectFormat()
    {
        using var drainer = new NotificationService();
        while (drainer.ReceiveNotification() != null) { }

        using var sut = new NotificationService();
        sut.SendNotification("Department", "5", "Math", EntityOperation.DELETE, "Admin");

        var notification = sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("Department 'Math' has been deleted", notification.Message);
        Assert.DoesNotContain("created", notification.Message);
        Assert.DoesNotContain("updated", notification.Message);
