    // ---- PaginatedList: HasNextPage with 0 total pages ----

    [Fact]
    public void PaginatedList_HasNextPage_WhenTotalPagesIsZero_ReturnsFalse()
    {
        var list = new PaginatedList<int>(new List<int>(), 0, 1, 10);
        Assert.Equal(0, list.TotalPages);
        Assert.False(list.HasNextPage); // 1 < 0 is false
    }

    [Fact]
    public void PaginatedList_HasPreviousPage_OnPageOne_WithZeroTotalPages_ReturnsFalse()
    {
        var list = new PaginatedList<int>(new List<int>(), 0, 1, 10);
        Assert.False(list.HasPreviousPage);
    }

    // ---- StudentsController: Create adds student with correct name ----

    [Fact]
    public void StudentsController_Create_Post_SavesCorrectStudentName()
    {
        using var context = TestHelpers.CreateInMemoryContext();
