        var course = new Course
        {
            CourseID = 5555,
            Title = "Boundary Test",
            Credits = 3,
            DepartmentID = context.Departments.First().DepartmentID
        };

        var fileMock = new Mock<IFormFile>();
        fileMock.Setup(f => f.Length).Returns(5 * 1024 * 1024); // Exactly 5MB
        fileMock.Setup(f => f.FileName).Returns("exact5mb.jpg");

        var result = controller.Create(course, fileMock.Object);

        // Should NOT fail on size validation (might fail on file write, but not size check)
        if (controller.ModelState.ContainsKey("teachingMaterialImage"))
        {
            var errors = controller.ModelState["teachingMaterialImage"]!.Errors;
            Assert.DoesNotContain(errors, e => e.ErrorMessage.Contains("5MB"));
        }
    }

    [Fact]
